import { describe, expect, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { examStudyFamilies, generateExamStudy, familyCoverage, requiredEvidenceChecks, studyManifestVersion, REQUIREMENT_BY_ID, EXAM_STUDY_PROFILES } from '@/lib/examStudy';
import { verifyDraft } from '@/lib/examStudy/evidence';
import type { StudyRequirementId } from '@/contracts/examStudy.contract';

const ids: StudyRequirementId[] = [
  'algebra.candidate-verification', 'algebra.equality-truth',
  'algebra.equation-classification', 'algebra.linear-model',
  'algebra.linear-simplify', 'written.rectangle-domain',
];
const seeds = [1, 2, 17, 71, 20261018, 20261019];
const output = '.qa-artifacts/math-exam-engine-remaining-20261019/unverified-runtime.json';

describe('read-only current exam-study unverified audit', () => {
  it('captures actual families, independent-gate negative controls and core formats', async () => {
    const all = examStudyFamilies();
    const requirements = [];
    for (const id of ids) {
      const course = id === 'written.rectangle-domain' ? '중3' : '중1';
      const profileId = course === '중3' ? 'kyungmyung-m3' : 'kyungmyung-m1';
      const mapped = all.filter(f => f.course === course && f.fulfills.some(r => r.requirement === id));
      expect(mapped).toHaveLength(1);
      const families = mapped.map(f => {
        const samples = seeds.flatMap(seed => [0, 1].map(variant => {
          const draft = f.generate(seed, variant);
          const verification = verifyDraft(f, draft);
          expect(verification.valid).toBe(true);
          expect(verification.checks).toEqual([]);
          expect(draft.figureSpec).toBeNull();
          expect(familyCoverage(f, id, verification, draft)).toBe('unverified');
          return {seed, variant, draft, verification, coverage: familyCoverage(f, id, verification, draft)};
        }));
        const base = samples[0]!.draft;
        const wrongAnswer = id === 'algebra.candidate-verification' ? '$x=999999$'
          : id === 'algebra.equality-truth' || id === 'algebra.equation-classification' ? '$0$개'
          : id === 'algebra.linear-simplify' ? '$999999x+999999$'
          : id === 'written.rectangle-domain' ? base.answer.replace(/세로 \$\d+/, '세로 $999999')
          : '$999999$';
        const negativeControls = [
          {name: 'wrong-answer', replacementAnswer: wrongAnswer, draft: {...base, answer: wrongAnswer}},
          {name: 'missing-printed-conditions', draft: {...base, content: '조건 없는 문항'}},
          {name: 'unrelated-solution', draft: {...base, solution: '무관한 풀이 자리 표시자'}},
          ...(base.rubric ? [{name: 'unrelated-rubric-expectations', draft: {...base, rubric: {...base.rubric, criteria: base.rubric.criteria.map(c => ({...c, expected: '무관한 설명'}))}}}] : []),
        ].map(({name, draft}) => ({name, mutatedDraft: draft, verification: verifyDraft(f, draft), coverage: familyCoverage(f, id, verifyDraft(f, draft), draft)}));
        for (const control of negativeControls) {
          expect(control.verification.valid).toBe(true);
          expect(control.verification.checks).toEqual([]);
          expect(control.coverage).toBe('unverified');
        }
        return {id: f.id, version: f.version, title: f.title, course: f.course, source: f.source,
          fulfills: f.fulfills, formats: f.formats, difficulties: f.difficulties,
          representation: f.representation, figureKinds: f.figureKinds,
          paramDomain: f.paramDomain, evidence: f.evidence ?? null,
          catalogCoverage: familyCoverage(f, id), samples, negativeControls};
      });
      const coreRuns = [];
      for (const seed of [71, 20261019]) for (const format of ['혼합', '단답형', '객관식', '서술형']) {
        const request = {course, profileId, requirementIds: [id], count: 1, format, seed, maxPerFamily: 1};
        const result = await generateExamStudy(request);
        expect(result.requirements).toHaveLength(1);
        expect(result.requirements[0]!.delivered).toBe(0);
        expect(result.requirements[0]!.status).toBe(families[0]!.formats.includes(format as never) || format === '혼합' ? 'unverified' : 'unavailable');
        for (const q of result.questions) {
          expect(q.figureSpec).toBeNull();
          expect(q.figureSvg).toBeNull();
          expect(q.requirements).toEqual([]);
        }
        coreRuns.push({request, result});
      }
      requirements.push({id, requirement: REQUIREMENT_BY_ID.get(id), profile: EXAM_STUDY_PROFILES.find(p => p.id === profileId),
        requiredEvidenceChecks: requiredEvidenceChecks(id), mappedFamilyCount: mapped.length, families, coreRuns});
    }
    const data = {schemaVersion: 1, capturedAt: new Date().toISOString(), node: process.version,
      sourceCommit: execFileSync('git', ['rev-parse', 'HEAD'], {encoding: 'utf8'}).trim(),
      manifestVersion: studyManifestVersion(all), totalFamilyRegistrations: all.length,
      sourceRegistrationCounts: Object.fromEntries(['authored', 'elementary', 'middle', 'high', 'native'].map(source => [source, all.filter(f => f.source === source).length])),
      directSeeds: seeds, directVariants: [0, 1], requirements};
    writeFileSync(output, JSON.stringify(data, null, 2) + '\n');
  });
});
